deployment.program:
import credits.aleo;
import pwn_config_demo.aleo;
import pwn_elastic_proposal_demo.aleo;
import pwn_hub_demo.aleo;
import token_registry.aleo;

program pwn_loan_demo.aleo;

struct Authority:
    domain as u8;
    account as address;
    salt as field;

struct Loan:
    loan_id as field;
    commitment_id as field;
    credit_amount as u64;
    collateral_asset as field;
    collateral_amount as u128;
    repayment_amount as u64;
    borrower_auth as field;
    lender_auth as field;

struct State:
    witness_hash as field;
    maturity as u32;
    status as u8;

mapping loans:
    key as field.public;
    value as State.public;

closure rounded:
    input r0 as u64;
    input r1 as u64;
    cast r0 into r2 as u128;
    cast r1 into r3 as u128;
    mul r2 r3 into r4;
    add r4 9999u128 into r5;
    div r5 10000u128 into r6;
    output r6 as u128;

function accept:
    input r0 as field.public;
    input r1 as field.public;
    input r2 as pwn_elastic_proposal_demo.aleo/Terms.public;
    input r3 as u64.public;
    input r4 as token_registry.aleo/Token.record;
    input r5 as field.private;
    assert.eq r4.token_id r2.collateral_asset;
    not r4.external_authorization_required into r6;
    assert.eq r6 true;
    call rounded r3 r2.collateral_ratio into r7;
    call rounded r3 r2.repayment_ratio into r8;
    cast r8 into r9 as u64;
    cast 2u8 self.signer r5 into r10 as Authority;
    hash.bhp256 r10 into r11 as field;
    cast r0 r1 r3 r2.collateral_asset r7 r9 r11 r2.lender_auth into r12 as Loan;
    hash.bhp256 r12 into r13 as field;
    call token_registry.aleo/transfer_private_to_public pwn_loan_demo.aleo r7 r4 into r14 r15;
    call pwn_elastic_proposal_demo.aleo/draw r1 r2 r3 self.signer into r16 r17;
    async accept r0 r13 r2.duration r15 r17 into r18;
    output r16 as credits.aleo/credits.record;
    output r14 as token_registry.aleo/Token.record;
    output r12 as Loan.public;
    output r18 as pwn_loan_demo.aleo/accept.future;

finalize accept:
    input r0 as field.public;
    input r1 as field.public;
    input r2 as u32.public;
    input r3 as token_registry.aleo/transfer_private_to_public.future;
    input r4 as pwn_elastic_proposal_demo.aleo/draw.future;
    contains loans[r0] into r5;
    not r5 into r6;
    assert.eq r6 true;
    add block.height r2 into r7;
    cast r1 r7 1u8 into r8 as State;
    set r8 into loans[r0];
    await r3;
    await r4;

function repay:
    input r0 as Loan.public;
    input r1 as credits.aleo/credits.record;
    input r2 as field.private;
    cast 2u8 self.signer r2 into r3 as Authority;
    hash.bhp256 r3 into r4 as field;
    assert.eq r0.borrower_auth r4;
    hash.bhp256 r0 into r5 as field;
    call pwn_elastic_proposal_demo.aleo/receive_repayment r0.commitment_id r1 r0.repayment_amount into r6 r7;
    call token_registry.aleo/transfer_public_to_private r0.collateral_asset self.signer r0.collateral_amount false into r8 r9;
    async repay r0 r5 r7 r9 into r10;
    output r6 as credits.aleo/credits.record;
    output r8 as token_registry.aleo/Token.record;
    output r10 as pwn_loan_demo.aleo/repay.future;

finalize repay:
    input r0 as Loan.public;
    input r1 as field.public;
    input r2 as pwn_elastic_proposal_demo.aleo/receive_repayment.future;
    input r3 as token_registry.aleo/transfer_public_to_private.future;
    get loans[r0.loan_id] into r4;
    assert.eq r4.witness_hash r1;
    assert.eq r4.status 1u8;
    lt block.height r4.maturity into r5;
    assert.eq r5 true;
    cast r1 r4.maturity 2u8 into r6 as State;
    set r6 into loans[r0.loan_id];
    await r2;
    await r3;

function claim_default:
    input r0 as Loan.public;
    input r1 as field.private;
    cast 1u8 self.signer r1 into r2 as Authority;
    hash.bhp256 r2 into r3 as field;
    assert.eq r0.lender_auth r3;
    hash.bhp256 r0 into r4 as field;
    call token_registry.aleo/transfer_public_to_private r0.collateral_asset self.signer r0.collateral_amount false into r5 r6;
    async claim_default r0 r4 r6 into r7;
    output r5 as token_registry.aleo/Token.record;
    output r7 as pwn_loan_demo.aleo/claim_default.future;

finalize claim_default:
    input r0 as Loan.public;
    input r1 as field.public;
    input r2 as token_registry.aleo/transfer_public_to_private.future;
    get loans[r0.loan_id] into r3;
    assert.eq r3.witness_hash r1;
    assert.eq r3.status 1u8;
    gte block.height r3.maturity into r4;
    assert.eq r4 true;
    cast r1 r3.maturity 3u8 into r5 as State;
    set r5 into loans[r0.loan_id];
    await r2;

constructor:
    assert.eq edition 0u16;
